    const relationLabel=value=>({supersedes:ui('版本取代','VERSION SUPERSEDES'),corrects:ui('来源纠正','SOURCE CORRECTS'),retracts:ui('来源撤回','SOURCE RETRACTS')})[String(value||'')]||String(value||ui('未知关系','UNKNOWN RELATION')).replaceAll('_',' ');
