    const platformBody=platformHealth.length?`<div><div class='wait-principle'><strong>${ui('登录由你在本机浏览器完成','Sign in only in your local browser')}</strong><p>${ui('LOGIN REQUIRED、SESSION STALE 或 OPEN PAGE 表示采集覆盖有空窗；系统不会索要或保存密码、Cookie、Session 或验证码。','LOGIN REQUIRED, SESSION STALE, or OPEN PAGE indicates a collection gap. The system never requests or stores passwords, cookies, sessions, or verification codes.')}</p></div><div class='table-wrap'><table class='data-table' data-testid='platform-access-health'><thead><tr><th>${ui('平台','Platform')}</th><th>${ui('启用','Enabled')}</th><th>${ui('访问状态','Access state')}</th><th>${ui('访问方式','Access mode')}</th><th>${ui('登录','Sign-in')}</th><th>${ui('最近心跳','Last heartbeat')}</th><th>${ui('页面可见 / 选择器','Visible / selectors')}</th></tr></thead><tbody>${platformHealth.map(item=>{const enabled=item.enabled!==false,state=String(item.access_state||'not_observed').toLowerCase(),login=Boolean(item.login_recommended),needsLogin=login&&['login_required','login_prompt','session_stale','not_observed'].includes(state);let label;if(!enabled)label=ui('已停用','DISABLED');else if(['login_required','login_prompt'].includes(state))label='LOGIN REQUIRED';else if(state==='session_stale')label='SESSION STALE';else if(['accessible','content_visible'].includes(state))label=ui('可访问','ACCESSIBLE');else if(state==='not_observed')label=login?ui('打开页面 / 登录','OPEN PAGE / SIGN IN'):ui('打开公开页面','OPEN PUBLIC PAGE');else label=stateLabel(state);const stateTone=!enabled?'unknown':['accessible','content_visible'].includes(state)?'ok':['login_required','login_prompt','session_stale'].includes(state)?'error':'warn';const pageUrl=safeUrl(item.page_url);return `<tr><td><div class='primary-cell'><div><strong>${esc(platformLabels[item.platform]||item.platform||ui('未知平台','Unknown platform'))}</strong><small>${pageUrl?`<a href='${esc(pageUrl)}' target='_blank' rel='noopener noreferrer'>${ui('打开已观察页面 ↗','Open observed page ↗')}</a>`:ui('尚未观察到页面','No page observed')}</small></div></div></td><td>${statusPill(enabled,enabled?ui('启用','ENABLED'):ui('停用','DISABLED'))}</td><td><span class='status-pill status-pill--${stateTone}'><i></i>${esc(label)}</span></td><td><span class='tag'>${esc(item.access_mode||'—')}</span></td><td>${needsLogin?`<span class='result-badge result-badge--rejected'>${ui('需要你处理','NEEDS YOU')}</span>`:login?`<span class='tag'>${ui('建议登录','RECOMMENDED')}</span>`:`<span class='tag'>${ui('无需登录','NOT REQUIRED')}</span>`}</td><td class='mono nowrap' title='${esc(dateTime(item.last_heartbeat_at))}'>${esc(age(item.last_heartbeat_at))}</td><td class='mono'>${item.visible===true?ui('可见','VISIBLE'):item.visible===false?ui('后台','BACKGROUND'):'—'} · ${esc(num(item.selector_count))}</td></tr>`;}).join('')}</tbody></table></div></div>`:empty(ui('尚无平台访问状态','No platform access status'),ui('后端尚未返回浏览器平台覆盖情况。','The backend has not returned browser platform coverage.'),'◉');
    const telegramRows=telegramItems.map(item=>{const sourceUrl=safeUrl(item.url),machine=item.preferred_machine_source||{},machineUrl=safeUrl(machine.url);return `<tr><td><div class='primary-cell'><div><strong>${sourceUrl?`<a href='${esc(sourceUrl)}' target='_blank' rel='noopener noreferrer'>${esc(item.display_name||item.handle)} ↗</a>`:esc(item.display_name||item.handle)}</strong><small>${esc(item.handle||'—')} · ${esc(item.category||'—')}</small></div></div></td><td><span class='tag'>${esc(item.source_role||'discovery_only')}</span></td><td><span class='tag'>${esc(item.identity_status||'unverified')}</span></td><td><span class='status-pill status-pill--unknown'><i></i>${ui('未采集','NOT COLLECTED')}</span></td><td>${machineUrl?`<a href='${esc(machineUrl)}' target='_blank' rel='noopener noreferrer'>${esc(machine.kind||ui('外部原始来源','external origin'))} ↗</a>`:'—'}</td></tr>`;}).join('');
