    const handoffBody=`<section style='margin-top:18px'><h3>${ui('合法替代链：Telegram 发现 → 站外原始页','Compliant fallback: Telegram discovery → external origin')}</h3><p>${ui('本机重新抓取并验证站外原始页。Telegram 只获得发现/传输归因；生成的观察固定为 identity/context，affects:investigation_only，不参与独立确认、候选、仓位或 Live。提交、拒绝、错误、零产出、重复和成功全部进入前向分母。','The local machine refetches and validates the external original page. Telegram receives discovery/transport attribution only; every observation is fixed to identity/context with affects:investigation_only and cannot influence independent confirmation, ranking, sizing, or Live. Submissions, rejections, errors, zero-yield, duplicates, and successes all remain in the forward denominator.')}</p>${handoffForm}<div class='source-summary'><div class='source-group'><div><strong>${esc(num(handoffSummary.attempts))}</strong><small>${ui('提交','ATTEMPTS')}</small></div></div><div class='source-group'><div><strong class='positive'>${esc(num(handoffSummary.verified))}</strong><small>${ui('验证成功','VERIFIED')}</small></div></div><div class='source-group'><div><strong>${esc(num(handoffSummary.zero_yield))}</strong><small>${ui('零产出','ZERO YIELD')}</small></div></div><div class='source-group'><div><strong class='negative'>${esc(num((handoffSummary.rejected||0)+(handoffSummary.error||0)))}</strong><small>${ui('拒绝 / 错误','REJECTED / ERROR')}</small></div></div></div>${handoffRows?`<div class='table-wrap'><table class='data-table' data-testid='telegram-handoff-attempts'><thead><tr><th>ID</th><th>${ui('入口 / 原始链接','Entry / origin')}</th><th>${ui('结果','Result')}</th><th>${ui('上下文事件','Context event')}</th><th>${ui('收到','Received')}</th></tr></thead><tbody>${handoffRows}</tbody></table></div>`:empty(ui('尚无站外链接提交','No external URL submissions yet'),ui('不会回填历史；第一条真实提交才开始记录。','No history is backfilled; recording starts with the first real submission.'),'↗')}</section>`;
