    const learningRows=learningItems.map(item=>{const closed=numeric(item.distinct_closed_paper_outcomes)||0,paperMature=item.rotation_active===true,maturity=item.maturity_progress??item.confidence;const paper=closed>0?`${num(closed)} · ${ui('胜率','win')} ${percent(item.paper_win_rate)} · ${ui('均值','mean')} ${percent(item.paper_mean_net_return,true)}`:'—';const roles=`F ${num(item.feature_observations)} · C ${num(item.confirmation_observations)} · I ${num(item.identity_observations)} · P ${num(item.promotion_observations)}`;return `<tr><td><div class='primary-cell'><div><strong>${esc(learningDisplay(item))}</strong><small>${esc(learningDimension[item.dimension]||item.dimension||ui('未知维度','unknown dimension'))}</small></div></div></td><td class='mono'>${esc(num(item.event_count))} / ${esc(num(item.observations))}</td><td class='mono'>${esc(roles)}<small class='learning-confidence'>${ui('feature / confirmation / identity / promotion','feature / confirmation / identity / promotion')}</small></td><td>${paperMature?`<span class='result-badge result-badge--candidate'>${ui('Paper 证据成熟','PAPER EVIDENCE MATURE')}</span>`:`<span class='tag'>${ui('收集样本','COLLECTING')}</span>`}<small class='learning-confidence'>${ui('最低结果门槛进度','minimum-outcome gate progress')} ${percent(maturity)}</small></td><td class='mono'>${item.early_event_rate===null||item.early_event_rate===undefined?'—':percent(item.early_event_rate)}</td><td class='mono'>${item.eligible_observation_rate===null||item.eligible_observation_rate===undefined?'—':percent(item.eligible_observation_rate)}<small class='learning-confidence'>${ui('必须早于首个候选决策','must predate first candidate')}</small></td><td class='mono'>${item.candidate_event_rate===null||item.candidate_event_rate===undefined?'—':percent(item.candidate_event_rate)}</td><td class='mono'>${esc(paper)}<small class='learning-confidence'>${ui('仅已选且平仓样本','selected & closed only')}</small></td><td class='mono'>${item.dimension==='event_topic'||item.dimension==='account_type'?ui('仅观察','observe only'):paperMature?`${ui('次级验证','secondary')} · ${Number(item.rotation_multiplier||1).toFixed(2)}×`:ui('未进入联合策略','not admitted')}</td></tr>`;}).join('');
    const learningBody=learningItems.length?`<div><div class='learning-disclaimer'><strong>${ui('Paper 来源效果只接受“最终决策 → 准入 cohort → 成交 → 平仓”的精确链','Paper source outcomes require an exact final-decision → admitted-cohort → fill → close chain')}</strong><p>${ui('系统在买入时冻结 decision/cohort，平仓时只归因给该 cohort 当时已准入的最早 feature/confirmation，并按真实手续费、滑点与已知卖出税计算净结果。旧的事件时间窗归因单独保留但不进入学习；缺少决策或 cohort 的平仓会明确记为未归因。这里仍是“被选中且已平仓”的条件样本，不证明某个媒体、平台、人物或题材导致收益，也不改变证据权重、候选、风控、仓位或 Live。','At buy time the system freezes the decision/cohort; at close it attributes only the earliest feature/confirmation admitted by that cohort and uses net results after recorded fees, slippage, and known sell tax. Legacy event-window attribution stays separate and cannot affect learning; closes missing a decision or cohort are explicitly unattributed. These remain conditional selected-and-closed samples, not proof that any source, platform, person, or topic caused returns, and they change no evidence weight, ranking, risk, sizing, or Live behavior.')}</p></div><div class='table-wrap learning-table' tabindex='0' aria-label='${ui('来源学习统计','Source learning statistics')}'><table class='data-table' data-testid='source-learning'><thead><tr><th>${ui('平台 / 类型 / 人物 / 热点','Platform / type / person / trend')}</th><th>${ui('事件 / 观察','Events / observations')}</th><th>${ui('证据角色 F / C / I / P','Evidence roles F / C / I / P')}</th><th>${ui('Paper 证据状态','Paper evidence state')}</th><th>${ui('最早合格证据','Early eligible')}</th><th>${ui('决策时合格率','Decision-time eligible rate')}</th><th>${ui('候选前关联率','Pre-candidate association')}</th><th>${ui('精确 cohort 平仓结果','Exact-cohort closed outcome')}</th><th>${ui('联合策略用途','Combined-policy use')}</th></tr></thead><tbody>${learningRows}</tbody></table></div></div>`:empty(ui('尚无来源学习样本','No source learning samples yet'),ui('系统不会生成演示趋势。先持续运行前向采集与 Paper 模拟；样本不足时观察轮换保持基线并继续探索。','No demo trends are generated. Keep forward collection and Paper simulation running; rotation stays at baseline while samples are insufficient.'),'◎');
    const learningMeta=`${esc(num(learningSummary.observations))} ${ui('条前向观察','forward observations')} · ${esc(num(learningSummary.attributed_closed_outcomes))} / ${esc(num(learningSummary.closed_attribution_attempts))} ${ui('精确归因 / 平仓尝试','exact attributed / closed attempts')} · ${esc(num(learningSummary.legacy_event_window_outcomes))} ${ui('个旧时间窗结果（排除）','legacy window outcomes excluded')} · ${esc(num(learningSummary.active_labels))} ${ui('个成熟 Paper 标签','mature Paper labels')}`;
    return `${pageHead(ui('信息源健康','Source health'),ui('静态/动态 RSS、链上源、浏览器桥、安全服务，以及不改变交易规则的前向学习。','Real health for static/dynamic RSS, on-chain sources, the browser bridge, safety services, and forward learning that cannot change trading rules.'))}${cards}<div class='stack'>${panel(ui('Telegram 接入边界与候选目录','Telegram access boundary & candidate directory'),telegramBody,`${telegramItems.length} ${ui('个候选 · 0 条自动消息','candidates · 0 automated messages')}`,true)}${panel(ui('Token 发现面暴露','Token discovery surface exposure'),discoveryBody,discoveryMeta,true)}${panel(ui('完整 Token 总体前向结果','Full token-universe forward outcomes'),universeBody,universeMeta,true)}${panel(ui('来源轮询暴露','Source polling exposure'),pollBody,pollMeta,true)}${panel(ui('同源前向学习闭环','Same-cohort forward learning closure'),closureBody,closureMeta,true)}${panel(ui('信息先行影子研究','Information-first shadow study'),informationFirstBody,informationFirstMeta,true)}${panel(ui('准入透明账本','Admission transparency ledger'),admissionBody,admissionMeta,true)}${panel(ui('预注册注意力实验','Preregistered attention experiment'),experimentBody,experimentMeta,true)}${panel(ui('趋势注意力策略','Trend attention policy'),attentionBody,attentionMeta,true)}${panel(ui('主题通道覆盖与影子学习','Topic coverage & shadow learning'),laneBody,laneMeta,true)}${panel(ui('账号选择性关注策略','Selective account attention policy'),accountExposureBody,accountExposureMeta,true)}${panel(ui('Token 语境前向结果','Token context forward outcomes'),contextBody,contextMeta,true)}${panel(ui('事件影子市场随访','Event shadow market follow-up'),followBody,followMeta,true)}${panel(ui('来源学习与观察优先级','Source learning & watch priority'),learningBody,learningMeta,true)}${panel(ui('社交平台访问 / 登录状态','Social platform access / sign-in status'),platformBody,`${platformHealth.length} ${ui('个平台','platforms')}`,true)}${panel(ui('采集器','Collectors'),body,`${items.length} ${ui('个已登记','registered')}`,true)}</div>`;
