  async function refreshOpenDetail(){
    const type=S.detailType,id=S.detailId;
    if(!S.detail||!type||!id)return;
    const request=detailRequests.begin(type,id);
    const scrollTop=E['drawer-content'].scrollTop;
    try{
      const detail=await api(`/${type==='event'?'events':'tokens'}/${encodeURIComponent(id)}`,{signal:request.signal});
      const returnedId=type==='event'?detail?.id:detail?.token_id;
      if(!detailRequests.isCurrent(request,type,id)||!S.detail||S.detailType!==type||String(S.detailId)!==String(id)||String(returnedId)!==String(id))return;
      S.detailData=detail;renderDetail(type,detail);E['drawer-content'].scrollTop=scrollTop;
    }catch(error){if(error?.name!=='AbortError'&&detailRequests.isCurrent(request,type,id))return;}
  }
  async function openDetail(type,id,push=false){
    if(!id)return;if(push){S.opener=document.activeElement;const target=`#/${type==='event'?'events':'tokens'}/${encodeURIComponent(id)}`;if(location.hash!==target)history.pushState({detail:true},'',target);}S.detail=true;S.detailType=type;S.detailData=null;document.querySelector('.app-shell').inert=true;E['detail-drawer'].classList.add('is-open');E['detail-drawer'].setAttribute('aria-hidden','false');E['drawer-scrim'].hidden=false;E['drawer-eyebrow'].textContent=type==='event'?ui('事件证据链','EVENT EVIDENCE CHAIN'):ui('Token 语境链','TOKEN CONTEXT CHAIN');E['drawer-title'].textContent=ui('加载详情…','Loading details…');E['drawer-content'].innerHTML=`<div class='initial-loader'><i></i><i></i><i></i></div>`;E['drawer-close'].focus({preventScroll:true});
    S.detailId=String(id);const request=detailRequests.begin(type,S.detailId);
    try{const detail=await api(`/${type==='event'?'events':'tokens'}/${encodeURIComponent(id)}`,{signal:request.signal});const returnedId=type==='event'?detail?.id:detail?.token_id;if(!detailRequests.isCurrent(request,type,id)||!S.detail||S.detailType!==type||String(S.detailId)!==String(id)||String(returnedId)!==String(id))return;S.detailData=detail;renderDetail(type,detail);}catch(error){if(error?.name==='AbortError'||!detailRequests.isCurrent(request,type,id)||!S.detail||S.detailType!==type||String(S.detailId)!==String(id))return;const items=list(S.cache.get(type==='event'?'events':'tokens'),type==='event'?'events':'tokens'),fallback=items.find(item=>String(item.id||item.token_id||`${item.chain||''}:${item.address||''}`)===String(id));if(fallback){S.detailData=fallback;renderDetail(type,fallback);E['drawer-content'].insertAdjacentHTML('afterbegin',`<div class='status-pill status-pill--warn' style='margin-bottom:12px'>${ui('详情接口不可用 · 正在显示列表快照','Detail API unavailable · Showing list snapshot')}</div>`);}else E['drawer-content'].innerHTML=`<div class='error-state'><div><span class='empty-glyph'>!</span><h3>${ui('详情读取失败','Failed to load details')}</h3><p>${esc(error.message)}</p></div></div>`;}
  }
  function closeDetail(historyAction=true){if(!S.detail)return;detailRequests.cancel();S.detail=false;S.detailType=null;S.detailId=null;S.detailData=null;document.querySelector('.app-shell').inert=false;E['detail-drawer'].classList.remove('is-open');E['detail-drawer'].setAttribute('aria-hidden','true');E['drawer-scrim'].hidden=true;const opener=S.opener;S.opener=null;if(opener?.isConnected)setTimeout(()=>opener.focus({preventScroll:true}),0);if(historyAction){if(history.state?.detail)history.back();else history.replaceState({},'',`#/${S.page}`);}}

  function bindSettings(){
    document.querySelectorAll('[data-setting-path]').forEach(input=>input.addEventListener('change',()=>{let value=input.value;if(input.dataset.valueType==='number')value=Number(value);if(input.dataset.valueType==='boolean')value=value==='true';if(/max_concurrent_agents$/i.test(input.dataset.settingPath))value=clamp(Math.round(Number(value)||2),1,2);setPath(S.changes,input.dataset.settingPath,value);markDirty();}));
    document.querySelectorAll('[data-platform-key]').forEach(input=>input.addEventListener('change',()=>{const draft=collectionDraft(),key=input.dataset.platformKey;if(Array.isArray(draft.platforms)){let item=draft.platforms.find(x=>String(x.id||x.platform||x.value||x)===key);if(item&&typeof item==='object')item.enabled=input.checked;else if(item!==undefined)draft.platforms[draft.platforms.indexOf(item)]={id:key,label:key,enabled:input.checked};else draft.platforms.push({id:key,label:key,enabled:input.checked});}else draft.platforms[key]=input.checked;markDirty();}));
    document.querySelectorAll('[data-account-index]').forEach(input=>input.addEventListener('change',()=>{const account=collectionDraft().watch_accounts[Number(input.dataset.accountIndex)],field=input.dataset.accountField;account[field]=input.type==='checkbox'?input.checked:field==='priority'?clamp(Math.round(Number(input.value)||3),1,5):input.value;markDirty();}));
    document.querySelectorAll('[data-topic-index]').forEach(input=>input.addEventListener('change',()=>{collectionDraft().topics[Number(input.dataset.topicIndex)]=input.value;markDirty();}));
    document.querySelectorAll('[data-remove-account]').forEach(button=>button.addEventListener('click',()=>{collectionDraft().watch_accounts.splice(Number(button.dataset.removeAccount),1);markDirty();render('settings',S.cache.get('settings'));}));
    document.querySelectorAll('[data-remove-topic]').forEach(button=>button.addEventListener('click',()=>{collectionDraft().topics.splice(Number(button.dataset.removeTopic),1);markDirty();render('settings',S.cache.get('settings'));}));
    document.querySelector('[data-add-account]')?.addEventListener('click',()=>{collectionDraft().watch_accounts.push({platform:'',handle:'',display_name:'',entity_id:'',url:'',enabled:true,priority:3});markDirty();render('settings',S.cache.get('settings'));});
    document.querySelector('[data-add-topic]')?.addEventListener('click',()=>{collectionDraft().topics.push('');markDirty();render('settings',S.cache.get('settings'));});
    document.getElementById('settings-form')?.addEventListener('submit',saveSettings);
  }
  async function walletMutation(path,method,payload,button) {
    const status=document.getElementById('wallet-operation-status'),label=button?.textContent||'';
    if(button){button.disabled=true;button.textContent=ui('处理中…','Working…');}if(status)status.textContent=ui('正在等待 Devnet 响应…','Waiting for the Devnet response…');
    try{
      const result=await api(path,{method,...(payload===undefined?{}:{body:JSON.stringify(payload)})});
      toast(get(result,'message','detail')||ui('Devnet 操作已完成','Devnet operation completed'),'success');
      S.cache.delete('wallet');await loadPage();
    }catch(error){if(status)status.textContent=`${ui('操作失败：','Operation failed: ')}${error.message}`;toast(`${ui('Devnet 操作失败：','Devnet operation failed: ')}${error.message}`,'error');if(button){button.disabled=false;button.textContent=label;}}
  }
